    #[test]
    fn instruction_legacy_comparison_transport_requires_actual_input_owner() {
        let raw = format!(
            r#"<w:p xmlns:w="{}"><w:fldSimple w:instr="CUSTOM" keep="{}"><x:opaque xmlns:x="urn:keep"/><w:r><w:t>cache</w:t></w:r></w:fldSimple></w:p>"#,
            crate::namespace::W_NS,
            "x".repeat(1024 * 1024)
        );
        let mut work = super::WordOperationWork::empty();
        let admitted = crate::document::admit_word_source(raw.as_bytes(), &[], None, None).unwrap();
        let paragraph = super::CT_P::from_xml_fragment_admitted(
            raw.as_bytes(),
            Some(
                &mut admitted
                    .controls_for(raw.as_bytes())
                    .with_field_origins(std::sync::Arc::clone(&work.field_origins), true),
            ),
            None,
            None,
        )
        .unwrap();
        let super::RunContent::Field(original) = &paragraph.runs[0].content[0] else {
            panic!("field")
        };
        work.register_original_fields(vec![original]).unwrap();
        work.normalized_output.lock().unwrap().allowance = 0;
        assert!(work.field_origins.lock().unwrap().incoming_record(original));
        for _ in 0..2 {
            assert!(
                super::field_publication_bytes(original, &mut work)
                    .unwrap()
                    .len()
                    > 1024 * 1024
            );
        }
        assert_eq!(work.normalized_output.lock().unwrap().emitted, 0);
        let super::FieldSource::Parsed { raw_xml, .. } = original.source.as_ref() else {
            panic!("parsed")
        };
        let start = raw_xml
            .windows(b"<x:opaque".len())
            .position(|w| w == b"<x:opaque")
            .unwrap();
        let end = start
            + raw_xml[start..]
                .windows(2)
                .position(|w| w == b"/>")
                .unwrap()
            + 2;
        let mut derived_xml = raw_xml.clone();
        derived_xml.drain(start..end);
        let derived_paragraph_xml = [
            b"<w:p xmlns:w=\"".as_slice(),
            crate::namespace::W_NS.as_bytes(),
            b"\">",
            &derived_xml,
            b"</w:p>",
        ]
        .concat();
        let paragraph = super::CT_P::from_xml_fragment(&derived_paragraph_xml).unwrap();
        let super::RunContent::Field(derived) = &paragraph.runs[0].content[0] else {
            panic!("derived")
        };
        let mut registry = work.field_origins.lock().unwrap();
        let original_map = registry.source_map(original).unwrap();
        let map = crate::document::WordSourceMap::concat(&[
            original_map.slice(0..start).unwrap(),
            original_map.slice(end..raw_xml.len()).unwrap(),
        ])
        .unwrap();
        assert!(map.entirely_original());
        let facts = registry.original_for(original);
        registry.register_forwarded(derived, map, facts).unwrap();
        assert!(!registry.incoming_record(derived));
        drop(registry);
        assert!(derived.is_unchanged());
        assert!(super::field_publication_bytes(derived, &mut work).is_err());
        assert_eq!(work.normalized_output.lock().unwrap().emitted, 0);
    }

    #[test]
    fn inner_xml_large_lock_edit_is_one_record_and_repeats_refuse_before_growth() {
        let raw = format!(
            r#"<w:p xmlns:w="{}"><w:fldSimple w:instr="CUSTOM"><x:opaque xmlns:x="urn:keep">{}</x:opaque><w:r><w:t>value</w:t></w:r></w:fldSimple></w:p>"#,
            crate::namespace::W_NS,
            "x".repeat(1024 * 1024)
        );
        let paragraph = super::CT_P::from_xml_fragment(raw.as_bytes()).unwrap();
        let super::RunContent::Field(original) = &paragraph.runs[0].content[0] else {
            panic!("field");
        };
        let mut field = original.clone();
        let mut work = super::WordOperationWork::model_field(original).unwrap();
        // Exact unchanged record transport does not consume generation work.
        for _ in 0..2 {
            let mut writer = quick_xml::Writer::new(work.model_source_output());
            super::write_field_with_result_properties(
                &mut writer,
                original,
                None,
                None,
                None,
                None,
                &mut work,
            )
            .unwrap();
        }
        assert_eq!(work.normalized_output.lock().unwrap().emitted, 0);
        super::FIELD_SOURCE_EDIT_MATERIALIZATIONS.set(0);
        field.locked = Some(true);
        let mut writer = quick_xml::Writer::new(work.model_source_output());
        super::write_field_with_result_properties(
            &mut writer,
            &field,
            None,
            None,
            None,
            None,
            &mut work,
        )
        .unwrap();
        let (first, _) = writer.into_inner().into_mapped_parts();
        assert!(
            std::str::from_utf8(&first)
                .unwrap()
                .contains("w:fldLock=\"1\"")
        );
        assert_eq!(work.normalized_output.lock().unwrap().emitted, first.len());
        assert_eq!(super::FIELD_SOURCE_EDIT_MATERIALIZATIONS.get(), 1);
        field.locked = Some(false);
        let before = field.clone();
        let mut writer = quick_xml::Writer::new(work.model_source_output());
        let error = super::write_field_with_result_properties(
            &mut writer,
            &field,
            None,
            None,
            None,
            None,
            &mut work,
        )
        .unwrap_err();
        assert!(error.to_string().contains("preflight source work"));
        assert_eq!(
            super::FIELD_SOURCE_EDIT_MATERIALIZATIONS.get(),
            1,
            "second actual source record refuses before its Vec materializes"
        );
        assert_eq!(field, before);
    }

    #[test]
    fn inner_xml_event_materialization_keeps_failed_work_spent() {
        struct RejectEscapedText;
        impl std::io::Write for RejectEscapedText {
            fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
                if bytes.windows(5).any(|piece| piece == b"&amp;") {
                    Err(std::io::Error::other("selected event transfer failed"))
                } else {
                    Ok(bytes.len())
                }
            }
            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let field = super::Field::new("CUSTOM", &"&".repeat(128));
        let original = field.clone();
        let mut positive = super::WordOperationWork::model_field(&field).unwrap();
        let mut writer = quick_xml::Writer::new(Vec::new());
        super::write_field_result_run(&mut writer, &field, None, None, None, None, &mut positive)
            .unwrap();
        assert!(
            String::from_utf8(writer.into_inner())
                .unwrap()
                .contains(&"&amp;".repeat(128))
        );
        let mut work = super::WordOperationWork::model_field(&field).unwrap();
        let mut produced_failures = 0;
        for _ in 0..256 {
            let mut writer = quick_xml::Writer::new(RejectEscapedText);
            let error = super::write_field_result_run(
                &mut writer,
                &field,
                None,
                None,
                None,
                None,
                &mut work,
            )
            .unwrap_err();
            if work.resource_refused() {
                assert!(error.to_string().contains("preflight source work"));
                break;
            }
            assert!(error.to_string().contains("selected event transfer failed"));
            produced_failures += 1;
        }
        assert!(
            produced_failures > 0 && produced_failures < 256,
            "failed transfer cannot refund already escaped XML production"
        );
        assert_eq!(field, original);
    }

    #[test]
    fn inner_xml_modeled_property_namespace_bytes_match_the_original_policy() {
        let properties = super::CT_RPr {
            font_ascii: Some("A&<>\"'é".into()),
            font_east_asia: Some("日本語".into()),
            font_ascii_theme: Some("minorHAnsi".into()),
            language: Some("en-GB".into()),
            language_east_asia: Some("ja-JP".into()),
            language_bidi: Some("ar-SA".into()),
            ..Default::default()
        };
        let word = crate::namespace::W_NS;
        type Scope<'a> = Option<&'a [(&'a str, &'a str)]>;
        let cases: &[(&str, super::XmlWriteRole, Scope<'_>)] = &[
            ("none", super::XmlWriteRole::Source, None),
            ("empty", super::XmlWriteRole::Source, Some(&[])),
            ("word", super::XmlWriteRole::Source, Some(&[("w", word)])),
            (
                "alias",
                super::XmlWriteRole::Source,
                Some(&[("w", "urn:foreign"), ("q", word)]),
            ),
            (
                "first",
                super::XmlWriteRole::Source,
                Some(&[("w", "urn:foreign"), ("z", word), ("q", word)]),
            ),
            (
                "fresh",
                super::XmlWriteRole::Source,
                Some(&[
                    ("w", "urn:foreign"),
                    ("rdocxW", "urn:a"),
                    ("rdocxW1", "urn:b"),
                    ("rdocxW01", "urn:c"),
                ]),
            ),
            (
                "leadingzero",
                super::XmlWriteRole::Source,
                Some(&[("w", "urn:foreign"), ("rdocxW0", "urn:a")]),
            ),
            ("default", super::XmlWriteRole::Source, Some(&[("", word)])),
            (
                "publication",
                super::XmlWriteRole::Publication,
                Some(&[("w", "urn:foreign"), ("q", word)]),
            ),
        ];
        for (name, role, scope) in cases {
            let work = super::WordOperationWork::empty();
            let emission = work.field_xml_emission();
            let mut writer = quick_xml::Writer::new(Vec::new());
            properties
                .write_xml_role(&mut writer, None, *role, *scope, Some(&emission))
                .unwrap();
            let actual = String::from_utf8(writer.into_inner()).unwrap();
            let expected = match *name {
                "none" => {
                    "<w:rPr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:rFonts xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" w:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" w:eastAsia=\"日本語\" w:asciiTheme=\"minorHAnsi\"/><w:lang xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" w:val=\"en-GB\" w:eastAsia=\"ja-JP\" w:bidi=\"ar-SA\"/></w:rPr>"
                }
                "empty" => {
                    "<w:rPr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:rFonts xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" w:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" w:eastAsia=\"日本語\" w:asciiTheme=\"minorHAnsi\"/><w:lang xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" w:val=\"en-GB\" w:eastAsia=\"ja-JP\" w:bidi=\"ar-SA\"/></w:rPr>"
                }
                "word" => {
                    "<w:rPr><w:rFonts w:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" w:eastAsia=\"日本語\" w:asciiTheme=\"minorHAnsi\"/><w:lang w:val=\"en-GB\" w:eastAsia=\"ja-JP\" w:bidi=\"ar-SA\"/></w:rPr>"
                }
                "alias" => {
                    "<q:rPr><q:rFonts q:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" q:eastAsia=\"日本語\" q:asciiTheme=\"minorHAnsi\"/><q:lang q:val=\"en-GB\" q:eastAsia=\"ja-JP\" q:bidi=\"ar-SA\"/></q:rPr>"
                }
                "first" => {
                    "<z:rPr><z:rFonts z:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" z:eastAsia=\"日本語\" z:asciiTheme=\"minorHAnsi\"/><z:lang z:val=\"en-GB\" z:eastAsia=\"ja-JP\" z:bidi=\"ar-SA\"/></z:rPr>"
                }
                "fresh" => {
                    "<rdocxW2:rPr xmlns:rdocxW2=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><rdocxW2:rFonts xmlns:rdocxW2=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" rdocxW2:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" rdocxW2:eastAsia=\"日本語\" rdocxW2:asciiTheme=\"minorHAnsi\"/><rdocxW2:lang xmlns:rdocxW2=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" rdocxW2:val=\"en-GB\" rdocxW2:eastAsia=\"ja-JP\" rdocxW2:bidi=\"ar-SA\"/></rdocxW2:rPr>"
                }
                "leadingzero" => {
                    "<rdocxW:rPr xmlns:rdocxW=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><rdocxW:rFonts xmlns:rdocxW=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" rdocxW:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" rdocxW:eastAsia=\"日本語\" rdocxW:asciiTheme=\"minorHAnsi\"/><rdocxW:lang xmlns:rdocxW=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" rdocxW:val=\"en-GB\" rdocxW:eastAsia=\"ja-JP\" rdocxW:bidi=\"ar-SA\"/></rdocxW:rPr>"
                }
                "default" => {
                    "<w:rPr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:rFonts xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" w:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" w:eastAsia=\"日本語\" w:asciiTheme=\"minorHAnsi\"/><w:lang xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" w:val=\"en-GB\" w:eastAsia=\"ja-JP\" w:bidi=\"ar-SA\"/></w:rPr>"
                }
                "publication" => {
                    "<w:rPr><w:rFonts w:ascii=\"A&amp;&lt;&gt;&quot;&apos;é\" w:eastAsia=\"日本語\" w:asciiTheme=\"minorHAnsi\"/><w:lang w:val=\"en-GB\" w:eastAsia=\"ja-JP\" w:bidi=\"ar-SA\"/></w:rPr>"
                }
                _ => unreachable!("closed fixture"),
            };
            assert_eq!(actual, expected, "original namespace bytes for {name}");
        }
    }

    #[test]
    fn inner_xml_modeled_toggle_and_color_preserve_context_order_and_debit() {
        for value in [false, true] {
            let properties = super::CT_RPr {
                bold: Some(value),
                bold_cs: Some(value),
                italic: Some(value),
                italic_cs: Some(value),
                caps: Some(value),
                small_caps: Some(value),
                strike: Some(value),
                dstrike: Some(value),
                outline: Some(value),
                shadow: Some(value),
                emboss: Some(value),
                imprint: Some(value),
                no_proof: Some(value),
                snap_to_grid: Some(value),
                vanish: Some(value),
                web_hidden: Some(value),
                rtl: Some(value),
                complex_script: Some(value),
                spec_vanish: Some(value),
                office_math: Some(value),
                color: Some("A&<>\"'é".into()),
                color_theme: Some("accent1".into()),
                color_theme_tint: Some(if value { 0xAF } else { 0 }),
                color_theme_shade: Some(if value { 0x10 } else { 0xFF }),
                ..Default::default()
            };
            let word = crate::namespace::W_NS;
            let scopes: &[&[(&str, &str)]] = &[
                &[],
                &[("w", word)],
                &[("w", "urn:foreign"), ("q", word)],
                &[
                    ("w", "urn:foreign"),
                    ("rdocxW", "urn:x"),
                    ("rdocxW1", "urn:y"),
                ],
            ];
            for role in [
                super::XmlWriteRole::Source,
                super::XmlWriteRole::Publication,
            ] {
                for scope in scopes {
                    let mut reference = quick_xml::Writer::new(Vec::new());
                    properties
                        .write_xml_role(&mut reference, None, role, Some(scope), None)
                        .unwrap();
                    let mut paragraph = super::CT_P::new();
                    paragraph.runs.push(super::field_run(
                        super::Field::new("CUSTOM", "x"),
                        Some(properties.clone()),
                    ));
                    let super::RunContent::Field(field) = &paragraph.runs[0].content[0] else {
                        panic!("field")
                    };
                    let mut work = super::WordOperationWork::model_field(field).unwrap();
                    work.register_model_result_properties(&paragraph).unwrap();
                    let emission = work.field_xml_emission();
                    let mut writer = quick_xml::Writer::new(work.normalized_output(None));
                    super::WORD_COLOR_EVENT_MATERIALIZATIONS.set(0);
                    super::WORD_BOLD_EVENT_MATERIALIZATIONS.set(0);
                    properties
                        .write_xml_role(&mut writer, None, role, Some(scope), Some(&emission))
                        .unwrap();
                    let (actual, _) = writer.into_inner().into_mapped_parts();
                    assert_eq!(actual, reference.into_inner());
                    assert_eq!(work.normalized_output.lock().unwrap().emitted, actual.len());
                    assert_eq!(super::WORD_COLOR_EVENT_MATERIALIZATIONS.get(), 1);
                    assert_eq!(super::WORD_BOLD_EVENT_MATERIALIZATIONS.get(), 1);
                    let xml = std::str::from_utf8(&actual).unwrap();
                    assert_eq!(
                        xml.matches(":val=\"false\"").count(),
                        if value { 0 } else { 20 }
                    );
                    assert!(xml.contains(if value {
                        "themeTint=\"AF\""
                    } else {
                        "themeTint=\"00\""
                    }));
                    assert!(xml.contains(if value {
                        "themeShade=\"10\""
                    } else {
                        "themeShade=\"FF\""
                    }));
                }
            }
        }
    }

    #[test]
    fn inner_xml_modeled_color_event_reserves_before_escaping_attributes() {
        let mut paragraph = super::CT_P::new();
        paragraph.runs.push(super::field_run(
            super::Field::new("CUSTOM", "x"),
            Some(super::CT_RPr {
                color: Some("&".repeat(16_384)),
                color_theme: Some("accent1".into()),
                color_theme_tint: Some(0xAF),
                color_theme_shade: Some(0),
                language: Some("en-GB".into()),
                language_east_asia: Some("ja-JP".into()),
                language_bidi: Some("ar-SA".into()),
                ..Default::default()
            }),
        ));
        let super::RunContent::Field(field) = &paragraph.runs[0].content[0] else {
            panic!("field")
        };
        let properties = paragraph.runs[0].properties.as_ref();
        let mut legacy = super::WordOperationWork::empty();
        let mut reference = quick_xml::Writer::new(Vec::new());
        super::write_field_result_run(
            &mut reference,
            field,
            None,
            properties,
            None,
            None,
            &mut legacy,
        )
        .unwrap();
        let reference = reference.into_inner();
        let mut full = super::WordOperationWork::model_field(field).unwrap();
        full.register_model_result_properties(&paragraph).unwrap();
        let mut writer = quick_xml::Writer::new(full.normalized_output(None));
        super::write_field_result_run(&mut writer, field, None, properties, None, None, &mut full)
            .unwrap();
        let (xml, _) = writer.into_inner().into_mapped_parts();
        assert_eq!(xml, reference);
        assert_eq!(full.normalized_output.lock().unwrap().emitted, xml.len());
        let start = xml
            .windows(8)
            .position(|bytes| bytes == b"<w:color")
            .unwrap();
        let close = start
            + xml[start..]
                .windows(2)
                .position(|bytes| bytes == b"/>")
                .unwrap();
        let mut bounded = super::WordOperationWork::model_field(field).unwrap();
        bounded
            .register_model_result_properties(&paragraph)
            .unwrap();
        bounded.normalized_output.lock().unwrap().allowance = start + (close - start - 1) - 1;
        super::WORD_COLOR_EVENT_MATERIALIZATIONS.set(0);
        let mut writer = quick_xml::Writer::new(bounded.normalized_output(None));
        assert!(
            super::write_field_result_run(
                &mut writer,
                field,
                None,
                properties,
                None,
                None,
                &mut bounded
            )
            .is_err()
        );
        assert_eq!(
            super::WORD_COLOR_EVENT_MATERIALIZATIONS.get(),
            0,
            "color QName and attributes must not grow before inherited admission"
        );
    }

