    #[test]
    fn inner_xml_modeled_compound_properties_keep_order_context_and_debit() {
        let input = format!(
            r#"<w:p xmlns:w="{}"><w:r><w:rPr><w:bdr w:val="single" w:sz="4294967295" w:space="0" w:color="AB&amp;é"/><w:shd w:val="clear" w:color="auto" w:themeColor="accent2" w:themeTint="00" w:themeShade="AF" w:fill="A&amp;&quot;é" w:themeFill="accent3" w:themeFillTint="10" w:themeFillShade="FF"/><w:fitText w:val="123" w:id="-2147483648"/><w:eastAsianLayout w:id="2147483647" w:combine="0" w:combineBrackets="curly" w:vert="1" w:vertCompress="0"/></w:rPr><w:t>x</w:t></w:r></w:p>"#,
            crate::namespace::W_NS
        );
        let mut paragraph = super::CT_P::from_xml_fragment(input.as_bytes()).unwrap();
        paragraph.runs[0].content =
            vec![super::RunContent::Field(super::Field::new("CUSTOM", "x"))];
        let properties = paragraph.runs[0].properties.as_ref().unwrap();
        let super::RunContent::Field(field) = &paragraph.runs[0].content[0] else {
            panic!("field")
        };
        let word = crate::namespace::W_NS;
        let scopes: &[&[(&str, &str)]] = &[
            &[],
            &[("w", word)],
            &[("w", "urn:foreign"), ("z", word), ("q", word)],
            &[
                ("w", "urn:foreign"),
                ("rdocxW", "urn:x"),
                ("rdocxW1", "urn:y"),
            ],
        ];
        for role in [
            super::XmlWriteRole::Source,
            super::XmlWriteRole::Publication,
        ] {
            for scope in scopes {
                let mut reference = quick_xml::Writer::new(Vec::new());
                properties
                    .write_xml_role(&mut reference, None, role, Some(scope), None)
                    .unwrap();
                let mut work = super::WordOperationWork::model_field(field).unwrap();
                work.register_model_result_properties(&paragraph).unwrap();
                let emission = work.field_xml_emission();
                let mut writer = quick_xml::Writer::new(work.normalized_output(None));
                super::WORD_COMPOUND_EVENT_MATERIALIZATIONS.set(0);
                properties
                    .write_xml_role(&mut writer, None, role, Some(scope), Some(&emission))
                    .unwrap();
                let (actual, _) = writer.into_inner().into_mapped_parts();
                assert_eq!(actual, reference.into_inner());
                assert_eq!(work.normalized_output.lock().unwrap().emitted, actual.len());
                assert_eq!(super::WORD_COMPOUND_EVENT_MATERIALIZATIONS.get(), 4);
                let xml = std::str::from_utf8(&actual).unwrap();
                assert!(xml.contains(":sz=\"4294967295\""));
                assert!(xml.contains(":space=\"0\""));
                assert!(xml.contains(":id=\"-2147483648\""));
                assert!(xml.contains(":combine=\"0\""));
                assert!(xml.contains(":vert=\"1\""));
                assert!(xml.contains(":vertCompress=\"0\""));
            }
        }
    }

