    #[test]
    fn inner_xml_simple_property_values_keep_order_bytes_and_one_debit() {
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:r><w:rPr><w:rStyle w:val="Base"/><w:spacing w:val="-10"/><w:w w:val="75"/><w:kern w:val="8"/><w:position w:val="2"/><w:sz w:val="24"/><w:szCs w:val="26"/><w:highlight w:val="yellow"/><w:u w:val="double"/><w:effect w:val="none"/><w:vertAlign w:val="superscript"/><w:em w:val="dot"/></w:rPr><w:t>x</w:t></w:r></w:p>"#,
            crate::namespace::W_NS
        );
        let mut paragraph = super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        paragraph.runs[0].content =
            vec![super::RunContent::Field(super::Field::new("CUSTOM", "x"))];
        let super::RunContent::Field(field) = &paragraph.runs[0].content[0] else {
            panic!("field")
        };
        let properties = paragraph.runs[0].properties.as_ref();
        let mut legacy = super::WordOperationWork::empty();
        let mut reference = quick_xml::Writer::new(Vec::new());
        super::write_field_result_run(
            &mut reference,
            field,
            None,
            properties,
            None,
            None,
            &mut legacy,
        )
        .unwrap();
        let mut full = super::WordOperationWork::model_field(field).unwrap();
        full.register_model_result_properties(&paragraph).unwrap();
        super::WORD_VALUE_EVENT_MATERIALIZATIONS.set(0);
        let mut writer = quick_xml::Writer::new(full.normalized_output(None));
        super::write_field_result_run(&mut writer, field, None, properties, None, None, &mut full)
            .unwrap();
        let (actual, _) = writer.into_inner().into_mapped_parts();
        assert_eq!(actual, reference.into_inner());
        assert_eq!(full.normalized_output.lock().unwrap().emitted, actual.len());
        assert_eq!(
            super::WORD_VALUE_EVENT_MATERIALIZATIONS.get(),
            12,
            "all concrete single-val properties use the shared producer"
        );
    }

    #[test]
    fn inner_xml_field_property_value_refuses_before_event_construction() {
        let mut paragraph = super::CT_P::new();
        paragraph.runs.push(super::field_run(
            super::Field::new("CUSTOM", "x"),
            Some(super::CT_RPr {
                style_id: Some("&".repeat(16_384)),
                ..Default::default()
            }),
        ));
        let super::RunContent::Field(field) = &paragraph.runs[0].content[0] else {
            panic!("field")
        };
        let properties = paragraph.runs[0].properties.as_ref();
        let mut legacy = super::WordOperationWork::empty();
        let mut reference = quick_xml::Writer::new(Vec::new());
        super::write_field_result_run(
            &mut reference,
            field,
            None,
            properties,
            None,
            None,
            &mut legacy,
        )
        .unwrap();
        let reference = reference.into_inner();
        let mut full = super::WordOperationWork::model_field(field).unwrap();
        full.register_model_result_properties(&paragraph).unwrap();
        let mut writer = quick_xml::Writer::new(full.normalized_output(None));
        super::write_field_result_run(&mut writer, field, None, properties, None, None, &mut full)
            .unwrap();
        let (xml, _) = writer.into_inner().into_mapped_parts();
        assert_eq!(xml, reference);
        assert_eq!(full.normalized_output.lock().unwrap().emitted, xml.len());
        let start = xml
            .windows(9)
            .position(|bytes| bytes == b"<w:rStyle")
            .unwrap();
        let close = start
            + xml[start..]
                .windows(2)
                .position(|bytes| bytes == b"/>")
                .unwrap();
        let payload = close - start - 1;
        let mut bounded = super::WordOperationWork::model_field(field).unwrap();
        bounded
            .register_model_result_properties(&paragraph)
            .unwrap();
        bounded.normalized_output.lock().unwrap().allowance = start + payload - 1;
        super::WORD_VALUE_EVENT_MATERIALIZATIONS.set(0);
        let mut writer = quick_xml::Writer::new(bounded.normalized_output(None));
        assert!(
            super::write_field_result_run(
                &mut writer,
                field,
                None,
                properties,
                None,
                None,
                &mut bounded
            )
            .is_err()
        );
        assert!(bounded.resource_refused());
        assert_eq!(
            super::WORD_VALUE_EVENT_MATERIALIZATIONS.get(),
            0,
            "property event must reserve before QName/attribute buffer allocation"
        );
    }

    fn parent_field_descendant_paragraph(route: &str, value: &str, font: bool) -> super::CT_P {
        use crate::content_control::{CT_Sdt, SdtContent};
        use crate::table::{CT_Row, CT_Tbl, CT_Tc, CellContent};
        let empty_control = || {
            let raw = format!(
                r#"<q:sdt xmlns:q="{}" xmlns:w="urn:foreign"><q:sdtContent/></q:sdt>"#,
                crate::namespace::W_NS
            );
            CT_Sdt::from_body_raw(raw.as_bytes(), &[]).unwrap()
        };
        let mut run = super::CT_R::new(if font { "leaf" } else { value });
        if font {
            run.properties = Some(super::CT_RPr {
                font_ascii: Some(value.into()),
                ..Default::default()
            });
        }
        let mut paragraph = super::CT_P::new();
        if route == "ruby" {
            paragraph.runs.push(super::CT_R::new("base"));
            paragraph.rubies.push(crate::ruby::CT_Ruby {
                ruby_text: vec![run],
                base_start: 0,
                base_end: 1,
                ..Default::default()
            });
            return paragraph;
        }
        let mut inner = empty_control();
        inner.content = vec![SdtContent::Run(run.clone())];
        let mut leaf = super::CT_P::new();
        leaf.runs.push(run);
        let mut cell = CT_Tc::new();
        cell.content = vec![CellContent::Paragraph(leaf)];
        let mut row = CT_Row::new();
        row.cells.push(cell.clone());
        let mut table = CT_Tbl::new();
        table.rows.push(row.clone());
        let mut outer = empty_control();
        outer.content = vec![match route {
            "inline" => SdtContent::ContentControl(inner),
            "paragraph" => {
                let mut child = super::CT_P::new();
                child.content_controls.push((0, 0, 0, inner));
                SdtContent::Paragraph(child)
            }
            "table" => SdtContent::Table(table),
            "row" => SdtContent::Row(row),
            "cell" => SdtContent::Cell(cell),
            "nested_table" => {
                let mut outer_cell = CT_Tc::new();
                outer_cell.content = vec![CellContent::Table(table)];
                SdtContent::Cell(outer_cell)
            }
            "row_boundary" => {
                let mut child = empty_control();
                child.content = vec![SdtContent::Cell(cell)];
                let mut boundary_row = CT_Row::new();
                boundary_row.content_controls.push((0, 0, child));
                let mut boundary_table = CT_Tbl::new();
                boundary_table.rows.push(boundary_row);
                SdtContent::Table(boundary_table)
            }
            "table_boundary" => {
                let mut child = empty_control();
                child.content = vec![SdtContent::Row(row)];
                let mut boundary_table = CT_Tbl::new();
                boundary_table.content_controls.push((0, 0, child));
                SdtContent::Table(boundary_table)
            }
            _ => panic!("unknown route"),
        }];
        paragraph.content_controls.push((0, 0, 0, outer));
        paragraph
    }

    fn assert_parent_field_descendant_guard(routes: &[&str], font: bool) {
        let value = "&<>\"'é\r".repeat(1024);
        let field = super::Field::new("CUSTOM", &value);
        let context = [("w", "urn:foreign"), ("q", crate::namespace::W_NS)];
        for route in routes {
            let paragraph = parent_field_descendant_paragraph(route, &value, font);
            let original = paragraph.clone();
            for role in [
                super::XmlWriteRole::Source,
                super::XmlWriteRole::Publication,
            ] {
                let source_role = role == super::XmlWriteRole::Source;
                let inherited = (role == super::XmlWriteRole::Source).then_some(context.as_slice());
                let mut reference = quick_xml::Writer::new(Vec::new());
                let mut legacy = super::WordOperationWork::empty();
                paragraph
                    .write_xml_content_in(&mut reference, role, inherited, &mut legacy, None)
                    .unwrap();
                let reference = reference.into_inner();
                let mut full = super::WordOperationWork::model_field(&field).unwrap();
                let emission = full.field_xml_emission();
                let mut writer = quick_xml::Writer::new(full.normalized_output(None));
                paragraph
                    .write_xml_content_in(&mut writer, role, inherited, &mut full, Some(&emission))
                    .unwrap();
                let (actual, _) = writer.into_inner().into_mapped_parts();
                assert_eq!(actual, reference, "{route} source={source_role}");
                assert_eq!(
                    full.normalized_output.lock().unwrap().emitted,
                    actual.len(),
                    "{route} source={source_role}"
                );
                let allowance = if font {
                    let at = actual
                        .windows(6)
                        .position(|bytes| bytes == b"rFonts")
                        .unwrap();
                    let start = actual[..at].iter().rposition(|byte| *byte == b'<').unwrap();
                    let end = start
                        + actual[start..]
                            .windows(2)
                            .position(|bytes| bytes == b"/>")
                            .unwrap()
                        + 2;
                    start + (end - start - 3) - 1
                } else {
                    actual
                        .windows(5)
                        .position(|bytes| bytes == b"&amp;")
                        .unwrap()
                        + super::escaped_source_len(&value).unwrap()
                        - 1
                };
                let mut bounded = super::WordOperationWork::model_field(&field).unwrap();
                bounded.normalized_output.lock().unwrap().allowance = allowance;
                let emission = bounded.field_xml_emission();
                super::WORD_TEXT_ESCAPE_MATERIALIZATIONS.set(0);
                super::WORD_FONT_EVENT_MATERIALIZATIONS.set(0);
                let mut writer = quick_xml::Writer::new(bounded.normalized_output(None));
                assert!(
                    paragraph
                        .write_xml_content_in(
                            &mut writer,
                            role,
                            inherited,
                            &mut bounded,
                            Some(&emission)
                        )
                        .is_err(),
                    "{route} source={source_role}"
                );
                assert!(bounded.resource_refused());
                let materializations = if font {
                    super::WORD_FONT_EVENT_MATERIALIZATIONS.get()
                } else {
                    super::WORD_TEXT_ESCAPE_MATERIALIZATIONS.get()
                };
                assert_eq!(
                    materializations, 0,
                    "{route} source={source_role}, font={font}: inherited refusal precedes materialization"
                );
                assert_eq!(paragraph, original);
            }
        }
    }

    #[test]
    fn parent_field_nested_controls_guard_text() {
        assert_parent_field_descendant_guard(
            &[
                "inline",
                "paragraph",
                "table",
                "row",
                "cell",
                "nested_table",
                "row_boundary",
                "table_boundary",
            ],
            false,
        );
    }
