    #[test]
    fn parent_field_collapsed_record_counts_retained_revisions_and_refuses_cumulatively() {
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:hyperlink w:anchor="target"><w:r><w:t>remove</w:t></w:r><x:kept xmlns:x="urn:producer"/><w:ins w:id="1" w:author="A"><w:r><w:t>revision</w:t></w:r></w:ins></w:hyperlink></w:p>"#,
            crate::namespace::W_NS
        );
        let paragraph = super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        let remove = vec![true; paragraph.runs.len()];
        let mut ordinary = paragraph.clone();
        ordinary.remove_runs_core(&remove, None).unwrap();
        let expected = ordinary
            .extra_xml
            .iter()
            .find(|(_, raw)| raw.starts_with(b"<w:hyperlink"))
            .unwrap()
            .1
            .clone();
        assert!(String::from_utf8_lossy(&expected).contains("revision"));
        let field = super::Field::new("CUSTOM", &"input".repeat(256));
        let mut work = super::WordOperationWork::model_field(&field).unwrap();
        work.normalized_output.lock().unwrap().allowance = expected.len() * 2 - 1;
        for round in 0..2 {
            let mut candidate = paragraph.clone();
            let emission = work.field_xml_emission();
            let result = candidate.remove_runs_core_in(
                &remove,
                None,
                None,
                Some(&mut work),
                Some(&emission),
            );
            if round == 0 {
                result.unwrap();
                let actual = &candidate
                    .extra_xml
                    .iter()
                    .find(|(_, raw)| raw.starts_with(b"<w:hyperlink"))
                    .unwrap()
                    .1;
                assert_eq!(actual, &expected);
                assert_eq!(
                    work.normalized_output.lock().unwrap().emitted,
                    expected.len(),
                    "NEW record includes retained revision transport"
                );
            } else {
                assert!(
                    result.is_err(),
                    "None lexical context must not swallow an inherited resource refusal"
                );
                assert!(work.resource_refused());
                assert!(work.normalized_output.lock().unwrap().emitted < expected.len() * 2);
            }
        }
        assert_eq!(
            paragraph,
            super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap()
        );
    }

