    #[test]
    fn parent_field_descendants_share_one_cumulative_output_ledger() {
        let value = "&".repeat(1024);
        let field = super::Field::new("CUSTOM", &value);
        let paragraph = parent_field_descendant_paragraph("paragraph", &value, false);
        let original = paragraph.clone();
        let mut work = super::WordOperationWork::model_field(&field).unwrap();
        let allowance = work.normalized_output.lock().unwrap().allowance;
        let mut successful = 0;
        for _ in 0..256 {
            let emission = work.field_xml_emission();
            let mut writer = quick_xml::Writer::new(work.normalized_output(None));
            match paragraph.write_xml_content_in(
                &mut writer,
                super::XmlWriteRole::Source,
                None,
                &mut work,
                Some(&emission),
            ) {
                Ok(()) => successful += 1,
                Err(_) => {
                    assert!(work.resource_refused());
                    break;
                }
            }
        }
        assert!(successful > 0 && successful < 256);
        assert!(
            work.resource_refused(),
            "descendants cannot renew the parent's allowance"
        );
        assert_eq!(work.normalized_output.lock().unwrap().allowance, allowance);
        assert_eq!(paragraph, original);
    }

    #[test]
    fn inner_xml_typed_run_text_keeps_bytes_and_refuses_before_escape() {
        let value = "&<>\"'é\r".repeat(1024);
        let field = super::Field::new("CUSTOM", &value);
        let runs = vec![super::CT_R::new(&value)];
        let original = runs.clone();
        let mut legacy = super::WordOperationWork::empty();
        let mut reference = quick_xml::Writer::new(Vec::new());
        super::write_typed_cached_runs(&mut reference, &runs, &[], None, None, None, &mut legacy)
            .unwrap();
        let reference = reference.into_inner();
        let mut full = super::WordOperationWork::model_field(&field).unwrap();
        let mut writer = quick_xml::Writer::new(full.normalized_output(None));
        super::write_typed_cached_runs(&mut writer, &runs, &[], None, None, None, &mut full)
            .unwrap();
        let (xml, _) = writer.into_inner().into_mapped_parts();
        assert_eq!(xml, reference);
        assert_eq!(
            full.normalized_output.lock().unwrap().emitted,
            xml.len(),
            "the actual escaped payload is not debited twice"
        );
        let payload = xml.windows(5).position(|bytes| bytes == b"&amp;").unwrap();
        let mut bounded = super::WordOperationWork::model_field(&field).unwrap();
        bounded.normalized_output.lock().unwrap().allowance =
            payload + super::escaped_source_len(&value).unwrap() - 1;
        super::WORD_TEXT_ESCAPE_MATERIALIZATIONS.set(0);
        let mut writer = quick_xml::Writer::new(bounded.normalized_output(None));
        assert!(
            super::write_typed_cached_runs(&mut writer, &runs, &[], None, None, None, &mut bounded)
                .is_err()
        );
        assert!(bounded.resource_refused());
        assert_eq!(
            super::WORD_TEXT_ESCAPE_MATERIALIZATIONS.get(),
            0,
            "typed mixed-run segmentation must forward the actual Field context"
        );
        assert_eq!(runs, original);
    }

