    #[test]
    fn field_source_edit_apply_refuses_before_changing_its_buffer() {
        let field = super::Field::new("CUSTOM", "input");
        let work = super::WordOperationWork::model_field(&field).unwrap();
        let raw = b"<w:fldSimple w:instr='OLD'/>".to_vec();
        let at = raw.windows(3).position(|bytes| bytes == b"OLD").unwrap();
        let allowance = work.normalized_output.lock().unwrap().allowance;
        work.reserve_inner_xml(allowance).unwrap();
        let mut updated = raw.clone();
        let edit = super::FieldSourceEdit::new(
            raw.len(),
            at..at + 3,
            vec![super::FieldSourcePiece::Escaped("NEW & instruction")],
        )
        .unwrap();
        assert!(
            edit.apply(&mut updated, &work).is_err(),
            "exhausted operation must refuse before surgery"
        );
        assert_eq!(updated, raw);
        assert_eq!(work.normalized_output.lock().unwrap().emitted, allowance);

        let work = super::WordOperationWork::model_field(&field).unwrap();
        let edit = super::FieldSourceEdit::new(
            raw.len(),
            at..at + 3,
            vec![super::FieldSourcePiece::Escaped("NEW & instruction")],
        )
        .unwrap();
        let projected = edit.projected;
        edit.apply(&mut updated, &work).unwrap();
        assert_eq!(updated, b"<w:fldSimple w:instr='NEW &amp; instruction'/>");
        assert_eq!(work.normalized_output.lock().unwrap().emitted, projected);
    }

