    #[test]
    fn scoped_model_distinct_current_values_can_share_retained_source() {
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:fldSimple w:instr="CUSTOM"><w:ins w:id="1" w:author="A"><w:r><w:t>old</w:t></w:r></w:ins></w:fldSimple></w:p>"#,
            crate::namespace::W_NS
        );
        let mut first = super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        let mut second = first.clone();
        let super::RunContent::Field(first_field) = &mut first.runs[0].content[0] else {
            panic!("field");
        };
        let super::RunContent::Field(second_field) = &mut second.runs[0].content[0] else {
            panic!("field");
        };
        assert!(std::sync::Arc::ptr_eq(
            &first_field.source,
            &second_field.source
        ));
        first_field.cached_result = "a".into();
        second_field.cached_result = "\t".repeat(5_000);
        let mut operation =
            crate::document::ScopedWordOperation::with_inputs(Vec::new(), vec![&first, &second])
                .unwrap();
        let (first_prepared, first_source) = operation.source_model_paragraph(&first).unwrap();
        assert_eq!(first_prepared.accepted_text(), "a");
        let (second_prepared, second_source) = operation.source_model_paragraph(&second).unwrap();
        assert_eq!(second_prepared.accepted_text(), "\t".repeat(5_000));
        let first_reopened = operation.source_paragraph(&first_source).unwrap();
        let second_reopened = operation.source_paragraph(&second_source).unwrap();
        assert_eq!(first_reopened.accepted_text(), "a");
        assert_eq!(second_reopened.accepted_text(), "\t".repeat(5_000));
    }

    #[test]
    fn retained_revision_transport_keeps_local_bounds_and_rejects_equal_copy_credit() {
        use std::io::Write;
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:ins w:id="1" w:author="A"><w:r><w:t>{}</w:t></w:r></w:ins></w:p>"#,
            crate::namespace::W_NS,
            "x".repeat(4096)
        );
        let paragraph = super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        let revision = &paragraph.revisions[0].2;
        let mut plain = quick_xml::Writer::new(Vec::new());
        revision
            .write_xml_with_role_override(&mut plain, None, super::XmlWriteRole::Source, None, None)
            .unwrap();
        let copied = plain.into_inner();
        let input = super::Field::new("CUSTOM", "");
        let mut work = super::WordOperationWork::model_field(&input).unwrap();
        let mut writer = quick_xml::Writer::new(work.normalized_output(Some(copied.len())));
        revision
            .write_xml_role_in(
                &mut writer,
                super::XmlWriteRole::Source,
                None,
                &mut work,
                None,
            )
            .unwrap();
        assert_eq!(writer.into_inner().bytes, copied);
        assert_eq!(work.normalized_output.lock().unwrap().emitted, 0);
        assert!(
            work.normalized_output
                .lock()
                .unwrap()
                .retained_revision
                .is_none()
        );
        let mut writer = work.normalized_output(Some(copied.len()));
        assert!(
            writer.write_all(&copied).is_err(),
            "an equal copied buffer is not the retained record"
        );
        assert!(
            writer.bytes.is_empty(),
            "refusal precedes copied output allocation"
        );

        let mut work = super::WordOperationWork::model_field(&input).unwrap();
        let mut writer = quick_xml::Writer::new(work.normalized_output(Some(copied.len() - 1)));
        assert!(
            revision
                .write_xml_role_in(
                    &mut writer,
                    super::XmlWriteRole::Source,
                    None,
                    &mut work,
                    None
                )
                .is_err()
        );
        assert!(
            writer.into_inner().bytes.is_empty(),
            "transport retains the local size guard"
        );
        assert!(
            work.normalized_output
                .lock()
                .unwrap()
                .retained_revision
                .is_none(),
            "failed transport drops its receipt"
        );
    }

    #[test]
    fn revision_result_refresh_preserves_raw_fallback_error_and_atomicity() {
        let paragraph = parse_paragraph(
            r#"<w:fldSimple w:instr="OUTER"><w:ins w:id="1" w:author="A"><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>INNER</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>old</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:ins></w:fldSimple>"#,
        );
        let mut parent = parsed_field(&paragraph, 0).clone();
        let mut run = super::CT_R::new("new");
        run.properties = Some(super::CT_RPr {
            revision_xml: vec![br#"<w:sz w:val="bad"/>"#.to_vec()],
            ..Default::default()
        });
        let child = super::Field::from_instruction(
            super::FieldInstruction::new("CUSTOM", Vec::new(), Vec::new()).unwrap(),
            super::FieldForm::Simple,
            vec![run],
        )
        .unwrap();
        child.validate_for_attachment().unwrap();
        *parent.cached_field_mut(0).unwrap() = child;
        let before = parent.clone();
        let error = parent.normalize_cached_result_owner().unwrap_err();
        // The checked semantic revision reader now diagnoses the malformed
        // property before the later source-path consistency check.
        assert!(
            matches!(
                &error,
                crate::OxmlError::InvalidValue(message)
                    if message == "w:sz/@w:val \"bad\" is not an integer measurement"
            ),
            "{error}"
        );
        assert_eq!(parent, before);
        assert!(std::sync::Arc::ptr_eq(&parent.source, &before.source));

        // The same local name in an opaque foreign property stays admissible.
        let mut opaque_parent = parsed_field(&paragraph, 0).clone();
        let mut opaque_run = super::CT_R::new("new");
        opaque_run.properties = Some(super::CT_RPr {
            revision_xml: vec![br#"<x:sz xmlns:x="urn:producer" x:val="bad"/>"#.to_vec()],
            ..Default::default()
        });
        *opaque_parent.cached_field_mut(0).unwrap() = super::Field::from_instruction(
            super::FieldInstruction::new("CUSTOM", Vec::new(), Vec::new()).unwrap(),
            super::FieldForm::Simple,
            vec![opaque_run],
        )
        .unwrap();
        opaque_parent.normalize_cached_result_owner().unwrap();
        assert_eq!(opaque_parent.cached_result, "new");
        assert!(
            String::from_utf8_lossy(
                &ordered_paragraph_xml(
                    &opaque_parent
                        .cached_result_owner_projection()
                        .unwrap()
                        .unwrap(),
                    None,
                )
                .unwrap()
            )
            .contains(r#"<x:sz xmlns:x="urn:producer" x:val="bad"/>"#)
        );
    }

    #[test]
    fn fieldless_revision_refresh_preserves_direct_error_and_ordinary_emission() {
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:ins w:id="1" w:author="A"><w:r><w:t>old</w:t></w:r></w:ins></w:p>"#,
            crate::namespace::W_NS
        );
        let mut paragraph = super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        let revision = &mut paragraph.revisions[0].2;
        revision
            .edit_accepted_paragraph(|paragraph| {
                paragraph.runs[0] = super::CT_R::new(&"new".repeat(4096));
                Ok(true)
            })
            .unwrap();
        assert_eq!(
            revision.content_paragraph().unwrap().accepted_text(),
            "new".repeat(4096)
        );
        let before = revision.clone();
        let error = revision
            .edit_accepted_paragraph(|paragraph| {
                paragraph.runs[0].properties = Some(super::CT_RPr {
                    revision_xml: vec![br#"<w:sz w:val="bad"/>"#.to_vec()],
                    ..Default::default()
                });
                Ok(true)
            })
            .unwrap_err()
            .to_string();
        assert!(error.contains("not an integer measurement"), "{error}");
        assert!(error.contains("w:sz"), "{error}");
        assert_eq!(*revision, before);
    }

    #[test]
    fn normalized_xml_materializations_share_the_operation_allowance() {
        let paragraph = super::CT_P {
            runs: vec![super::CT_R::new("text<&")],
            ..super::CT_P::new()
        };
        let input = super::Field::new("CUSTOM", "text<&");
        let mut work = super::WordOperationWork::model_field(&input).unwrap();
        let local = input.normalization_work_budget().unwrap();
        let mut completed = 0;
        for _ in 0..256 {
            match super::ordered_paragraph_xml_in(&paragraph, None, &mut work, Some(local)) {
                Ok(xml) => {
                    completed += 1;
                    assert!(std::str::from_utf8(&xml).unwrap().contains("text&lt;&amp;"));
                }
                Err(error) => {
                    assert!(error.to_string().contains("preflight source work"));
                    break;
                }
            }
        }
        assert!(
            completed > 1 && completed < 256,
            "repeated actual XML publication must not renew credit"
        );
        let ledger = work.normalized_output.lock().unwrap();
        assert!(ledger.refused);
        assert!(
            ledger.emitted <= ledger.allowance,
            "refusal precedes output growth"
        );
        assert_eq!(paragraph.accepted_text(), "text<&");
    }

    #[test]
    fn structural_field_writer_reuses_one_materialization_context() {
        use crate::table::{CT_Row, CT_Tbl, CT_Tc, CellContent};
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:fldSimple w:instr="CUSTOM"><w:ins w:id="1" w:author="a"><w:r><w:t>old</w:t></w:r></w:ins></w:fldSimple></w:p>"#,
            crate::namespace::W_NS,
        );
        let mut paragraph = super::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        let super::RunContent::Field(field) = &mut paragraph.runs[0].content[0] else {
            panic!("typed field");
        };
        field.cached_result = "\t".repeat(1_000);
        let mut cell = CT_Tc::new();
        cell.content = vec![CellContent::Paragraph(paragraph)];
        let mut row = CT_Row::new();
        row.cells.push(cell);
        let mut table = CT_Tbl::new();
        table.rows.push(row);
        let original = table.clone();
        let mut work = super::WordOperationWork::model_fields(table.writer_field_roots()).unwrap();
        let mut completed = 0;
        for _ in 0..256 {
            let mut writer = quick_xml::Writer::new(Vec::new());
            match table.write_xml_role_in(
                &mut writer,
                super::XmlWriteRole::Source,
                None,
                &mut work,
                None,
            ) {
                Ok(()) => {
                    completed += 1;
                    assert!(
                        writer
                            .into_inner()
                            .windows(6)
                            .any(|bytes| bytes == b"w:tab/")
                    );
                }
                Err(error) => {
                    assert!(error.to_string().contains("preflight source work"));
                    break;
                }
            }
        }
        assert!(
            completed > 1 && completed < 256,
            "structural writers must not renew field credit"
        );
        assert_eq!(
            table, original,
            "private failed emission must leave its model unchanged"
        );
    }

