    #[test]
    fn field_result_parts_match_real_run_decoding_without_generated_xml() {
        for value in [
            "",
            "plain",
            " a ",
            "\r",
            "\r\n",
            "<&\"'&amp;",
            "é\t中\nlast",
            "\t\n\t",
            "tail\n",
            "\u{2003}x\u{2003}",
        ] {
            let direct = super::FieldResultParts::new(value)
                .map(super::FieldResultPart::into_run_content)
                .collect::<Vec<_>>();
            let mut writer = quick_xml::Writer::new(
                br#"<w:r xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">"#
                    .to_vec(),
            );
            super::write_field_result_content(&mut writer, value).unwrap();
            writer.get_mut().extend_from_slice(b"</w:r>");
            let parsed = super::parse_run_raw(&writer.into_inner(), &["w".into()], None).unwrap();
            assert_eq!(direct, parsed.content, "{value:?}");
        }
        let actual = super::FieldResultParts::new("\tA\n")
            .map(super::FieldResultPart::into_run_content)
            .collect::<Vec<_>>();
        assert_eq!(
            actual,
            vec![
                super::RunContent::Tab,
                super::RunContent::Text(super::CT_Text {
                    text: "A".into(),
                    preserve_space: false,
                }),
                super::RunContent::Break(super::BreakType::Line),
            ]
        );
    }

