    #[test]
    fn citation_and_bibliography_bare_operands_keep_opcode_specific_association() {
        let instruction = parse_field_instruction(
            r#"CITATION first \l 1033 \p 17 \v 3 \n \m second \f "before " \y \s " after" \t \l 1036"#,
        );
        assert_eq!(instruction.arguments, [FieldArgument::Text("first".into())]);
        assert_eq!(
            instruction
                .switches
                .iter()
                .map(|switch| switch.name.as_str())
                .collect::<Vec<_>>(),
            ["l", "p", "v", "n", "m", "f", "y", "s", "t", "l"]
        );
        assert!(
            instruction
                .switches
                .iter()
                .filter(|switch| matches!(switch.name.as_str(), "n" | "y" | "t"))
                .all(|switch| switch.argument.is_none())
        );
        let bibliography =
            parse_field_instruction(r#"BIBLIOGRAPHY \l 1033 \m first \m "second tag" \f"#);
        assert!(bibliography.arguments.is_empty());
        assert_eq!(bibliography.switches.len(), 4);
        assert!(bibliography.switches[3].argument.is_none());
        let unrelated = parse_field_instruction(r#"UNKNOWN first \l 1033"#);
        assert_eq!(unrelated.arguments.len(), 2);
        assert!(unrelated.switches[0].argument.is_none());
    }

    #[test]
    fn parse_simple_paragraph() {
        let p = parse_paragraph(r#"<w:r><w:t>Hello World</w:t></w:r>"#);
        assert_eq!(p.text(), "Hello World");
        assert_eq!(p.runs.len(), 1);
    }

    #[test]
    fn prepared_final_writer_streams_only_its_live_transport_and_restores_scope() {
        let raw = b"<q:fldSimple q:instr='PAGE'><q:r><q:t>cache</q:t></q:r></q:fldSimple>";
        let prefixes = vec![
            "q".into(),
            format!("\0q\0{}", crate::namespace::W_NS),
            "\0w\0urn:foreign".into(),
        ];
        let field = super::parse_simple_field(raw, &prefixes, None)
            .unwrap()
            .unwrap();
        let mut paragraph = super::CT_P::new();
        paragraph.runs.push(super::CT_R {
            content: vec![super::RunContent::Field(field.clone())],
            ..super::CT_R::new("")
        });
        let mut work = super::WordOperationWork::model_fields(vec![&field]).unwrap();
        let before = work.original_input_state_for_test();
        let expected =
            super::published_field_root_plan(raw, &field, &[("w", crate::namespace::W_NS)])
                .unwrap()
                .unwrap();
        let added = expected.added_bytes(raw);
        assert!(added > 0);
        let projected = expected.projected;
        super::FIELD_PUBLICATION_CONSTRUCTIONS.set(0);
        let mut final_writer = quick_xml::Writer::new(Vec::new());
        super::write_prepared_validation_xml(&paragraph, &mut final_writer, &mut work).unwrap();
        assert_eq!(
            super::FIELD_PUBLICATION_CONSTRUCTIONS.get(),
            0,
            "the exact final writer has no separate Field record"
        );
        assert_eq!(work.normalized_output.lock().unwrap().emitted, added);
        assert!(
            work.normalized_output
                .lock()
                .unwrap()
                .final_validation_writer
                .is_none()
        );
        super::validate_word_owner_fragment(final_writer.get_ref(), b"p", false).unwrap();
        assert_eq!(work.original_input_state_for_test(), before);

        // A distinct fresh normalization writer, while the final writer remains
        // live, retains the old owned-record producer and cumulative demand.
        let nested_work = super::WordOperationWork::model_fields(vec![&field]).unwrap();
        nested_work.normalized_output.lock().unwrap().allowance = projected * 2;
        let previous = nested_work
            .normalized_output
            .lock()
            .unwrap()
            .final_validation_writer
            .replace(std::ptr::from_ref(&final_writer) as usize);
        let lease = super::FinalValidationWriterLease {
            previous,
            work: std::sync::Arc::clone(&nested_work.normalized_output),
        };
        for attempt in 0..3 {
            let mut nested = quick_xml::Writer::new(nested_work.normalized_output(None));
            let result = super::write_field_raw_output(
                &mut nested,
                raw,
                &field,
                None,
                Some(&[("w", crate::namespace::W_NS)]),
                &nested_work,
                None,
            );
            if attempt < 2 {
                result.unwrap();
            } else {
                assert!(result.is_err());
                assert!(nested.into_inner().into_mapped_parts().0.is_empty());
            }
        }
        assert_eq!(
            nested_work.normalized_output.lock().unwrap().emitted,
            projected * 2
        );
        assert_eq!(super::FIELD_PUBLICATION_CONSTRUCTIONS.get(), 2);
        drop(lease);
        assert!(
            nested_work
                .normalized_output
                .lock()
                .unwrap()
                .final_validation_writer
                .is_none()
        );
        assert!(
            !final_writer.get_ref().is_empty(),
            "the witnessed final writer stayed live"
        );

        let mut bad = super::CT_P::new();
        bad.extra_xml.push((
            super::ROOT_ATTRIBUTES_POSITION,
            b"<rdocxRootAttributes bad='&missing;'/>".to_vec(),
        ));
        let mut output = quick_xml::Writer::new(Vec::new());
        assert!(super::write_prepared_validation_xml(&bad, &mut output, &mut work).is_err());
        assert!(
            work.normalized_output
                .lock()
                .unwrap()
                .final_validation_writer
                .is_none()
        );

        let state = std::sync::Arc::clone(&work.normalized_output);
        let prior = state
            .lock()
            .unwrap()
            .final_validation_writer
            .replace(std::ptr::from_ref(&final_writer) as usize);
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _lease = super::FinalValidationWriterLease {
                previous: prior,
                work: std::sync::Arc::clone(&state),
            };
            panic!("exercise the production lexical receipt's unwind restoration");
        }));
        assert!(result.is_err());
        assert!(state.lock().unwrap().final_validation_writer.is_none());
    }

    #[test]
    fn prepared_final_writer_unchanged_transport_and_insertions_have_exact_demand() {
        for (prefix, namespace) in [("w", true), ("q", false)] {
            let declaration = if namespace {
                format!(" xmlns:{prefix}=\"{}\"", crate::namespace::W_NS)
            } else {
                String::new()
            };
            let raw = format!(
                "<{prefix}:fldSimple{declaration} {prefix}:instr='PAGE'><{prefix}:r><{prefix}:t>cache</{prefix}:t></{prefix}:r></{prefix}:fldSimple>"
            );
            let prefixes = vec![
                prefix.into(),
                format!("\0{prefix}\0{}", crate::namespace::W_NS),
            ];
            let field = super::parse_simple_field(raw.as_bytes(), &prefixes, None)
                .unwrap()
                .unwrap();
            let mut paragraph = super::CT_P::new();
            paragraph.runs.push(super::CT_R {
                content: vec![super::RunContent::Field(field.clone())],
                ..super::CT_R::new("")
            });
            let mut work = super::WordOperationWork::model_fields(vec![&field]).unwrap();
            let plan = super::published_field_root_plan(
                raw.as_bytes(),
                &field,
                &[("w", crate::namespace::W_NS)],
            )
            .unwrap()
            .unwrap();
            let added = plan.added_bytes(raw.as_bytes());
            if namespace {
                assert_eq!(added, 0);
            } else {
                assert!(added > 0);
                work.normalized_output.lock().unwrap().allowance = added * 2;
            }
            let mut expected = quick_xml::Writer::new(Vec::new());
            paragraph.to_xml(&mut expected).unwrap();
            for attempt in 0..3 {
                let mut output = quick_xml::Writer::new(Vec::new());
                let result =
                    super::write_prepared_validation_xml(&paragraph, &mut output, &mut work);
                if namespace || attempt < 2 {
                    result.unwrap();
                    assert_eq!(output.into_inner(), *expected.get_ref());
                } else {
                    assert!(result.is_err());
                }
                assert!(
                    work.normalized_output
                        .lock()
                        .unwrap()
                        .final_validation_writer
                        .is_none()
                );
            }
            assert_eq!(work.normalized_output.lock().unwrap().emitted, added * 2);
        }
    }

    #[test]
    fn discarded_namespace_values_keep_decoder_errors_before_later_attributes() {
        for (raw, first) in [
            (
                br#"<p xmlns:unused="&broken;" plain="&later;"/>"#.as_slice(),
                "broken",
            ),
            (
                br#"<p plain="&earlier;" xmlns:unused="&broken;"/>"#.as_slice(),
                "earlier",
            ),
        ] {
            let mut reader = quick_xml::Reader::from_reader(raw);
            let quick_xml::events::Event::Empty(element) = reader.read_event().unwrap() else {
                panic!("root")
            };
            let error = super::RootAttributePlan::read(&element, &[])
                .err()
                .expect("even unused declarations must decode");
            assert!(error.to_string().contains(first), "{error}");
        }

        let mut reader = quick_xml::Reader::from_reader(
            br#"<p xmlns="urn:unused" xmlns:q="urn:&amp;owned" plain="A&amp;B"/>"#.as_slice(),
        );
        let quick_xml::events::Event::Empty(element) = reader.read_event().unwrap() else {
            panic!("root")
        };
        let plan = super::RootAttributePlan::read(&element, &[]).unwrap();
        assert_eq!(plan.attributes, vec![("plain".into(), "A&B".into())]);
        assert!(plan.used_prefixes.is_empty());
        assert!(plan.emit_in(&[], None).unwrap().is_some());
    }

    #[test]
    fn direct_root_plan_preserves_real_namespace_resolver_limits_and_spelling() {
        let mut records = vec![
            r#"<rdocxRootAttributes m:Ignorable="missing" xmlns:m="http://schemas.openxmlformats.org/markup-compatibility/200&#54;"/>"#.to_owned(),
            r#"<rdocxRootAttributes i:type="missing:T" xmlns:i="http://www.w3.org/2001/XMLSchema-&#105;nstance"/>"#.to_owned(),
            r#"<rdocxRootAttributes q:a="v" xmlns:q="http://www.w3.org/XML/1998/namespace"/>"#.to_owned(),
            r#"<rdocxRootAttributes q:a="v" xmlns:q="&#104;ttp://www.w3.org/XML/1998/namespace"/>"#.to_owned(),
            format!(
                r#"<rdocxRootAttributes w14:paraId="A" plain=" /w14:name &lt;w14:name" xmlns:w14="{}"/>"#,
                super::W14_NS
            ),
        ];
        for count in [256, 257] {
            let attributes = (0..count)
                .map(|index| format!(" q{index}:a='v' xmlns:q{index}='urn:{index}&amp;x'"))
                .collect::<String>();
            records.push(format!("<rdocxRootAttributes{attributes}/>"));
        }
        let owner = quick_xml::events::BytesStart::from_content(
            format!(
                "w:p xmlns:w=\"{}\" xmlns:w14=\"{}\"",
                crate::namespace::W_NS,
                super::W14_NS
            ),
            3,
        );
        let _scope = super::emitted_binding_scope(&owner, true, false).unwrap();
        for (index, raw) in records.iter().enumerate() {
            let mut reader = quick_xml::Reader::from_reader(raw.as_bytes());
            let quick_xml::events::Event::Empty(element) = reader.read_event().unwrap() else {
                panic!("record")
            };
            let prefixes = crate::numbering::word_prefixes_at(&element, &[]).unwrap();
            let bindings = prefixes
                .iter()
                .filter_map(|value| value.strip_prefix('\0')?.split_once('\0'))
                .collect::<Vec<_>>();
            for role in [
                super::XmlWriteRole::Source,
                super::XmlWriteRole::Publication,
            ] {
                let legacy = (|| -> crate::Result<Vec<u8>> {
                    let record = super::RootAttributePlan::read(&element, &bindings)?
                        .emit_in(&bindings, None)?
                        .unwrap();
                    let mut root = quick_xml::events::BytesStart::new("w:r");
                    super::push_root_attribute_record(&mut root, &record, None, role)?;
                    let mut output = quick_xml::Writer::new(Vec::new());
                    output.write_event(quick_xml::events::Event::Empty(root))?;
                    Ok(output.into_inner())
                })()
                .map_err(|error| error.to_string());
                let direct = (|| -> crate::Result<Vec<u8>> {
                    let plan = super::RootAttributePlan::read(&element, &bindings)?;
                    let mut root = super::FieldXmlStart::new("w:r", None)?;
                    plan.merge_run_root(&mut root, &element, &prefixes, role)?;
                    let mut output = quick_xml::Writer::new(Vec::new());
                    root.write(&mut output, true)?;
                    Ok(output.into_inner())
                })()
                .map_err(|error| error.to_string());
                assert_eq!(direct, legacy, "real resolver/source policy case {index}");
                if index == 5 {
                    assert!(direct.is_ok(), "256 used declarations remain supported");
                }
                if index == 6 {
                    assert!(
                        direct.is_err(),
                        "257 used declarations preserve the existing library refusal"
                    );
                }
            }
        }
    }

    #[test]
    fn run_root_plan_direct_merge_legacy_scope_transcripts() {
        let word = crate::namespace::W_NS;
        let records = [
            r#"<rdocxRootAttributes z:opaque="a&amp;&lt;&quot;&#9;é" xmlns:z="urn:opaque"/>"#.to_owned(),
            format!(
                r#"<rdocxRootAttributes q:id="x" xmlns:q="{word}" xmlns:w="urn:foreign&amp;uri"/>"#
            ),
            r#"<rdocxRootAttributes q:id="x" xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/200&#54;/main" xmlns:w="urn:foreign&amp;uri"/>"#.to_owned(),
            format!(
                r#"<rdocxRootAttributes mc:Ignorable="q" q:id="x" xmlns:mc="{}" xmlns:q="urn:opaque"/>"#,
                crate::namespace::MC_NS
            ),
            format!(
                r#"<rdocxRootAttributes mc:Ignorable="w" w:id="x" xmlns:mc="{}" xmlns:w="urn:foreign"/>"#,
                crate::namespace::MC_NS
            ),
            r#"<rdocxRootAttributes i:type="q:Type" xmlns:i="http://www.w3.org/2001/XMLSchema-instance" xmlns:q="urn:opaque&amp;uri"/>"#.to_owned(),
            r#"<rdocxRootAttributes i:type="missing:Type" xmlns:i="http://www.w3.org/2001/XMLSchema-instance"/>"#.to_owned(),
            r#"<rdocxRootAttributes q:id="1" z:id="2" xmlns:q="urn:same" xmlns:z="urn:same"/>"#.to_owned(),
            r#"<rdocxRootAttributes first="ok" bad="&missing;"/>"#.to_owned(),
            r#"<rdocxRootAttributes q:id="1"/>"#.to_owned(),
            format!(r#"<rdocxRootAttributes plain="v" xmlns="{word}"/>"#),
        ];
        let mut transcripts = Vec::new();
        for raw in records {
            for role in [
                super::XmlWriteRole::Source,
                super::XmlWriteRole::Publication,
            ] {
                let mut run = super::CT_R::new("");
                run.extra_xml.push(raw.as_bytes().to_vec());
                run.extra_xml_positions
                    .push(super::RAW_ROOT_ATTRIBUTES_FLAG | super::RAW_RUN_LOCAL_BINDINGS_FLAG);
                let mut localized = Vec::new();
                let outcome = super::run_xml_root_in(&run, None, &mut localized, role, None)
                    .and_then(|(root, _)| {
                        let mut writer = quick_xml::Writer::new(Vec::new());
                        root.write(&mut writer, true)?;
                        Ok(String::from_utf8(writer.into_inner()).unwrap())
                    })
                    .map_err(|error| error.to_string());
                transcripts.push(format!(
                    "{}: {outcome:?}",
                    if role == super::XmlWriteRole::Source {
                        "Source"
                    } else {
                        "Publication"
                    }
                ));
            }
        }
        assert_eq!(
            transcripts,
            [
                r###"Source: Ok("<w:r z:opaque=\"a&amp;&lt;&quot;\té\" xmlns:z=\"urn:opaque\"/>")"###,
                r###"Publication: Ok("<w:r z:opaque=\"a&amp;&lt;&quot; é\" xmlns:z=\"urn:opaque\"/>")"###,
                r###"Source: Ok("<w:r q:id=\"x\" xmlns:q=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:w=\"urn:foreign&amp;uri\"/>")"###,
                r###"Publication: Ok("<w:r q:id=\"x\" xmlns:q=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"/>")"###,
                r###"Source: Ok("<w:r q:id=\"x\" xmlns:q=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:w=\"urn:foreign&amp;uri\"/>")"###,
                r###"Publication: Ok("<w:r q:id=\"x\" xmlns:q=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"/>")"###,
                r###"Source: Ok("<w:r mc:Ignorable=\"q\" q:id=\"x\" xmlns:q=\"urn:opaque\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\"/>")"###,
                r###"Publication: Ok("<w:r mc:Ignorable=\"q\" q:id=\"x\" xmlns:q=\"urn:opaque\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\"/>")"###,
                r###"Source: Ok("<w:r mc:Ignorable=\"w\" w:id=\"x\" xmlns:w=\"urn:foreign\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\"/>")"###,
                r###"Publication: Err("invalid value: element XML namespace-valued root attribute referencing foreign w is unsupported")"###,
                r###"Source: Ok("<w:r i:type=\"q:Type\" xmlns:q=\"urn:opaque&amp;uri\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"/>")"###,
                r###"Publication: Ok("<w:r i:type=\"q:Type\" xmlns:q=\"urn:opaque&amp;uri\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"/>")"###,
                r###"Source: Ok("<w:r i:type=\"missing:Type\" xmlns:i=\"http://www.w3.org/2001/XMLSchema-instance\"/>")"###,
                r###"Publication: Err("invalid value: element XML namespace-valued root attribute has an unbound prefix")"###,
                r###"Source: Err("invalid value: duplicate expanded root attribute `id`")"###,
                r###"Publication: Err("invalid value: duplicate expanded root attribute `id`")"###,
                r###"Source: Err("XML error: at 1..8: unrecognized entity `missing`")"###,
                r###"Publication: Err("XML error: at 1..8: unrecognized entity `missing`")"###,
                r###"Source: Err("invalid value: root attribute prefix `q` is unbound")"###,
                r###"Publication: Err("invalid value: root attribute prefix `q` is unbound")"###,
                r###"Source: Ok("<w:r plain=\"v\" xmlns=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"/>")"###,
                r###"Publication: Ok("<w:r plain=\"v\" xmlns=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"/>")"###,
            ]
        );
    }

    #[test]
    fn run_root_attribute_plan_preserves_late_error_and_context() {
        let word = crate::namespace::W_NS;
        let root = format!(
            "<w:r xmlns:w=\"{word}\" xmlns:q=\"urn:same\" xmlns:z=\"urn:same\" q:a=\"1\" z:a=\"2\">"
        );
        for (child, expected) in [
            ("<w:commentReference w:id=\"bad\"/>", "parse int error"),
            ("<w:t>text</w:t>", "duplicate expanded root attribute"),
        ] {
            let source = format!("{root}{child}</w:r>");
            let error = super::parse_run_raw(source.as_bytes(), &[], None)
                .unwrap_err()
                .to_string();
            assert!(error.contains(expected), "{error}");
        }
        let start = BytesStart::from_content("w:r w:rsidR=\"a&amp;b\"", 3);
        let bare = vec!["w".to_owned()];
        let record = super::capture_root_attribute_record(&start, &bare)
            .unwrap()
            .unwrap();
        let record = String::from_utf8(record).unwrap();
        assert!(record.contains("a&amp;b"));
        assert!(record.contains(word));
        let explicit = vec!["w".to_owned(), "\0w\0urn:foreign".to_owned()];
        let record = super::capture_root_attribute_record(&start, &explicit)
            .unwrap()
            .unwrap();
        assert!(String::from_utf8(record).unwrap().contains("urn:foreign"));
    }

    #[test]
    fn paragraph_root_attributes_reject_alias_duplicates_and_authored_id_wins() {
        let duplicate = br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:a="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:b="http://schemas.microsoft.com/office/word/2010/wordml" a:paraId="11111111" b:paraId="22222222"/>"#;
        let error = CT_P::from_xml_fragment(duplicate).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("duplicate expanded root attribute")
        );

        let source = br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:i="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:x="urn:producer" i:paraId="11111111" i:textId="22222222" x:keep="yes"/>"#;
        let paragraph = CT_P::from_xml_fragment(source).unwrap();
        let mut output = Vec::new();
        paragraph
            .to_xml_with_para_id(&mut Writer::new(&mut output), Some("AAAAAAAA"))
            .unwrap();
        let output = String::from_utf8(output).unwrap();
        assert_eq!(output.matches(":paraId=").count(), 1, "{output}");
        assert!(output.contains(r#"w14:paraId="AAAAAAAA""#), "{output}");
        assert!(output.contains(r#"i:textId="22222222""#), "{output}");
        assert!(output.contains(r#"x:keep="yes""#), "{output}");
    }

