    #[test]
    fn run_source_raw_growth_is_admitted_before_expansion() {
        let uri = format!("urn:{}", "u".repeat(400));
        let bindings = vec![
            ("x".to_owned(), uri.clone()),
            ("w".to_owned(), crate::namespace::W_NS.to_owned()),
        ];
        let destination = [("w", crate::namespace::W_NS)];
        let raw = b"<x:opaque/>";
        let added = run_source_raw_added(raw, &bindings, &destination).unwrap();
        assert!(
            added > raw.len(),
            "the crafted child needs a retained declaration"
        );
        let mut writer = Writer::new(Vec::new());
        let mut budget = raw.len() + added - 1;
        let mut context = RunRawContext {
            foreign_word_namespace: None,
            bindings: &bindings,
            localized: &[],
            source_context: Some(&destination),
            source_budget: Some(&mut budget),
            emission: None,
        };
        let error = write_run_raw_source(&mut writer, raw, &mut context).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("field namespace publication exceeds normalization work budget"),
            "{error}"
        );
        assert!(
            writer.get_ref().is_empty(),
            "over-budget raw expansion was written"
        );
        let mut writer = Writer::new(Vec::new());
        let mut budget = raw.len() + added;
        let mut context = RunRawContext {
            foreign_word_namespace: None,
            bindings: &bindings,
            localized: &[],
            source_context: Some(&destination),
            source_budget: Some(&mut budget),
            emission: None,
        };
        write_run_raw_source(&mut writer, raw, &mut context).unwrap();
        assert_eq!(budget, raw.len());
        assert!(
            String::from_utf8(writer.into_inner())
                .unwrap()
                .contains("xmlns:x=")
        );
    }

    #[test]
    fn a_reopened_paragraph_identity_does_not_rebind_the_prefix_its_part_root_owns() {
        // A paragraph written with a bare `w14:paraId` and reopened used to
        // come back carrying its own `xmlns:w14`, so saving the reopened
        // document produced different bytes from the save it was read from.
        let w_ns = crate::namespace::W_NS;
        let xml = format!(
            r#"<w:document xmlns:w="{w_ns}" xmlns:w14="{W14_NS}"><w:body><w:p w14:paraId="00000001"/></w:body></w:document>"#
        );
        let document = crate::document::CT_Document::from_xml(xml.as_bytes()).unwrap();
        let first = document.to_xml().unwrap();
        let reopened = crate::document::CT_Document::from_xml(&first).unwrap();
        let second = reopened.to_xml().unwrap();
        assert_eq!(first, second);
        let output = String::from_utf8(second).unwrap();
        assert!(output.contains(r#"w14:paraId="00000001""#), "{output}");
        assert_eq!(output.matches("xmlns:w14").count(), 1, "{output}");
        let paragraph = output.find("<w:p ").unwrap();
        let declaration = output.find("xmlns:w14=").unwrap();
        assert!(declaration < paragraph, "{output}");

        // An unknown standalone wrapper cannot borrow the same-part promise,
        // so the paragraph keeps the declaration its own root needs.
        let source =
            format!(r#"<w:p xmlns:w="{w_ns}" xmlns:w14="{W14_NS}" w14:paraId="00000001"/>"#);
        let paragraph = CT_P::from_xml_fragment(source.as_bytes()).unwrap();
        let mut output = Vec::new();
        paragraph.to_xml(&mut Writer::new(&mut output)).unwrap();
        let output = String::from_utf8(output).unwrap();
        assert!(output.contains(r#"w14:paraId="00000001""#), "{output}");
        assert!(
            output.contains("xmlns:w14"),
            "a standalone paragraph lost the binding its identity needs: {output}"
        );
    }

    #[test]
    fn dropping_w14_identities_keeps_every_other_retained_attribute() {
        // An alias prefix goes with the identities it bound, and a record
        // left with nothing else goes away.
        let w_ns = crate::namespace::W_NS;
        let source = format!(
            r#"<w:p xmlns:w="{w_ns}" xmlns:i="{W14_NS}" xmlns:x="urn:producer" i:paraId="11111111" w:rsidR="00A1B2C3" i:textId="22222222" x:keep="yes"/>"#
        );
        let mut paragraph = CT_P::from_xml_fragment(source.as_bytes()).unwrap();
        drop_w14_paragraph_identities(&mut paragraph.extra_xml).unwrap();
        let mut output = Vec::new();
        paragraph.to_xml(&mut Writer::new(&mut output)).unwrap();
        let output = String::from_utf8(output).unwrap();
        assert!(
            output.starts_with(r#"<w:p w:rsidR="00A1B2C3" x:keep="yes""#),
            "{output}"
        );
        assert!(output.contains(r#"xmlns:x="urn:producer""#), "{output}");
        assert!(!output.contains("Id="), "{output}");
        assert!(!output.contains("xmlns:i="), "{output}");

        let source = format!(
            r#"<w:p xmlns:w="{w_ns}" xmlns:w14="{W14_NS}" w14:paraId="11111111" w14:textId="22222222"/>"#
        );
        let mut paragraph = CT_P::from_xml_fragment(source.as_bytes()).unwrap();
        drop_w14_paragraph_identities(&mut paragraph.extra_xml).unwrap();
        assert!(paragraph.extra_xml.is_empty(), "{:?}", paragraph.extra_xml);
    }

    #[test]
    fn a_part_root_w14_declaration_uses_the_live_bom_physical_origin() {
        let input = br#"<q:document xmlns:q="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><q:body><q:p w14:paraId="1234"/></q:body></q:document>"#;
        for prefix in [&b"\xef\xbb\xbf"[..], &b"\xef\xbb\xbf \n"[..]] {
            let mut actual = [prefix, input].concat();
            let mut unprefixed = input.to_vec();
            declare_w14_on_part_root(&mut unprefixed).unwrap();
            declare_w14_on_part_root(&mut actual).unwrap();
            assert_eq!(actual, [prefix, unprefixed.as_slice()].concat());
        }
    }

    #[test]
    fn a_part_root_declares_w14_only_when_its_content_needs_it() {
        let w_ns = crate::namespace::W_NS;
        let part = |root: &str, body: &str| {
            format!(
                r#"<?xml version="1.0"?><w:document xmlns:w="{w_ns}"{root}><w:body>{body}</w:body></w:document>"#
            )
            .into_bytes()
        };
        let identity = r#"<w:p w14:paraId="00000001"/>"#;
        let mut unbound = part("", identity);
        declare_w14_on_part_root(&mut unbound).unwrap();
        assert_eq!(
            unbound,
            part(&format!(r#" xmlns:w14="{W14_NS}""#), identity)
        );
        crate::document::CT_Document::from_xml(&unbound).unwrap();

        for unchanged in [
            part(&format!(r#" xmlns:w14="{W14_NS}""#), identity),
            part(r#" xmlns:w14="urn:other""#, identity),
            part("", r#"<w:p><w:r><w:t>w14</w:t></w:r></w:p>"#),
        ] {
            let mut xml = unchanged.clone();
            declare_w14_on_part_root(&mut xml).unwrap();
            assert_eq!(xml, unchanged);
        }
    }

