    #[test]
    fn hyperlink_complex_source_retains_inter_run_trivia() {
        let mut paragraph = parse_paragraph(concat!(
            r#"<w:hyperlink w:anchor="destination">"#,
            "\n  ",
            r#"<w:r><w:fldChar w:fldCharType="begin"/></w:r>"#,
            "\n  <!-- hyperlink-before-instruction -->",
            r#"<w:r><w:instrText>REF destination</w:instrText></w:r>"#,
            "<?producer hyperlink-before-separator?>",
            r#"<w:r><w:fldChar w:fldCharType="separate"/></w:r>"#,
            "\n  <!-- hyperlink-before-result -->",
            r#"<w:r><w:t>cached</w:t></w:r>"#,
            "<?producer hyperlink-before-end?>",
            r#"<w:r><w:fldChar w:fldCharType="end"/></w:r>"#,
            "\n",
            r#"</w:hyperlink>"#,
        ));
        let RunContent::Field(field) = &mut paragraph.runs[0].content[0] else {
            panic!("expected hyperlink field")
        };
        let (captured, _) = field.source_replacement().unwrap().unwrap();
        for preserved in [
            "\n  <!-- hyperlink-before-instruction -->",
            "<?producer hyperlink-before-separator?>",
            "\n  <!-- hyperlink-before-result -->",
            "<?producer hyperlink-before-end?>",
        ] {
            assert!(
                String::from_utf8_lossy(captured).contains(preserved),
                "missing {preserved}: {}",
                String::from_utf8_lossy(captured)
            );
        }

        field.cached_result = "updated hyperlink".to_owned();
        field.dirty = Some(false);
        let output = serialized_paragraph(&paragraph);
        for preserved in [
            "<!-- hyperlink-before-instruction -->",
            "<?producer hyperlink-before-separator?>",
            "<!-- hyperlink-before-result -->",
            "<?producer hyperlink-before-end?>",
        ] {
            assert!(output.contains(preserved), "missing {preserved}: {output}");
        }
        assert!(output.contains("updated hyperlink"), "{output}");
        assert!(output.contains("<w:hyperlink"), "{output}");
    }

    #[test]
    fn hyperlink_frame_is_the_explicit_source_context_for_its_runs() {
        let xml = format!(
            r#"<w:p xmlns:w="{w}"><w:hyperlink xmlns:x="urn:producer" w:anchor="target"><w:r><w:t>ab</w:t><x:mark/></w:r></w:hyperlink><w:r><w:t>after</w:t></w:r></w:p>"#,
            w = crate::namespace::W_NS
        );
        let paragraph = CT_P::from_xml_fragment_checked(xml.as_bytes()).unwrap();
        let context = [("w", crate::namespace::W_NS)];
        let mut output = Vec::new();
        paragraph
            .write_xml_core(
                &mut Writer::new(&mut output),
                None,
                XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        let output = String::from_utf8(output).unwrap();
        // The hyperlink owns the declaration and the run records the binding
        // it actually borrows, so the opaque child completes nothing itself.
        assert_eq!(output.matches("xmlns:x=").count(), 2, "{output}");
        assert!(output.contains("<x:mark/>"), "{output}");
        assert!(!output.contains("<x:mark xmlns:x="), "{output}");
        // The emitted source reopens under the same frame and repeats exactly.
        let inner = output
            .strip_prefix("<w:p>")
            .and_then(|rest| rest.strip_suffix("</w:p>"))
            .expect("bare source paragraph root");
        let reopened = CT_P::from_xml_fragment_checked(
            format!(
                r#"<w:p xmlns:w="{w}">{inner}</w:p>"#,
                w = crate::namespace::W_NS
            )
            .as_bytes(),
        )
        .unwrap();
        let mut second = Vec::new();
        reopened
            .write_xml_core(
                &mut Writer::new(&mut second),
                None,
                XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        assert_eq!(second, output.as_bytes());
    }

