    #[test]
    fn ruby_mutation_source_round_trips_under_explicit_context() {
        let xml = format!(
            r#"<w:p xmlns:w="{w}"><w:r><w:t>base</w:t></w:r><w:ruby><w:rubyPr><w:rubyAlign w:val="center"/></w:rubyPr><w:rt><w:r><w:t>read</w:t></w:r></w:rt><w:rubyBase><w:r><w:t>base</w:t></w:r></w:rubyBase></w:ruby></w:p>"#,
            w = crate::namespace::W_NS
        );
        let mut paragraph = CT_P::from_xml_fragment_checked(xml.as_bytes()).unwrap();
        let ruby = paragraph.rubies.first_mut().expect("ruby annotation");
        ruby.ruby_text = vec![CT_R::new("changed")];
        ruby.properties.as_mut().expect("ruby properties").align =
            Some(crate::ruby::ST_RubyAlign::DistributeSpace);
        let context = [("w", crate::namespace::W_NS)];
        let mut output = Vec::new();
        paragraph
            .write_xml_core(
                &mut Writer::new(&mut output),
                None,
                XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        let output = String::from_utf8(output).unwrap();
        assert!(output.contains("<w:t>changed</w:t>"), "{output}");
        assert!(output.contains("w:val=\"distributeSpace\""), "{output}");
        assert!(output.contains("<w:t>base</w:t>"), "{output}");
        // The mutated annotation reopens under the same explicit frame and
        // repeats its Source bytes exactly.
        let inner = output
            .strip_prefix("<w:p>")
            .and_then(|rest| rest.strip_suffix("</w:p>"))
            .expect("bare source paragraph root");
        let reopened = CT_P::from_xml_fragment_checked(
            format!(
                r#"<w:p xmlns:w="{w}">{inner}</w:p>"#,
                w = crate::namespace::W_NS
            )
            .as_bytes(),
        )
        .unwrap();
        let ruby = reopened.rubies.first().expect("reopened ruby annotation");
        assert_eq!(
            ruby.ruby_text.iter().map(CT_R::text).collect::<String>(),
            "changed"
        );
        assert_eq!(
            ruby.properties.as_ref().expect("reopened properties").align,
            Some(crate::ruby::ST_RubyAlign::DistributeSpace)
        );
        let mut second = Vec::new();
        reopened
            .write_xml_core(
                &mut Writer::new(&mut second),
                None,
                XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        assert_eq!(second, output.as_bytes());
    }

