    #[test]
    fn split_run_keeps_properties_space_and_later_markers_in_order() {
        let mut paragraph = parse_paragraph(concat!(
            r#"<w:bookmarkStart w:id="1" w:name="mark"/>"#,
            r#"<w:r><w:rPr><w:b/></w:rPr><w:t>Hello world</w:t></w:r>"#,
            r#"<w:bookmarkEnd w:id="1"/><w:r><w:t>!</w:t></w:r>"#,
        ));
        paragraph.split_run(0, 6).unwrap();

        let texts = paragraph.runs.iter().map(CT_R::text).collect::<Vec<_>>();
        assert_eq!(texts, ["Hello ", "world", "!"]);
        assert_eq!(paragraph.runs[0].properties, paragraph.runs[1].properties);
        let output = serialized_paragraph(&paragraph);
        assert!(
            output.contains(r#"<w:t xml:space="preserve">Hello </w:t>"#),
            "{output}"
        );
        let world = output.find(">world<").unwrap();
        let bookmark_end = output.find("bookmarkEnd").unwrap();
        let exclamation = output.find(">!<").unwrap();
        assert!(
            world < bookmark_end && bookmark_end < exclamation,
            "{output}"
        );
    }

    #[test]
    fn collapsed_hyperlink_source_growth_is_reserved_before_construction() {
        let mut paragraph = parse_paragraph(concat!(
            r#"<w:hyperlink xmlns:x="urn:producer" w:anchor="target"><x:raw/><w:r><w:t>ab</w:t></w:r><x:end/></w:hyperlink>"#,
            r#"<w:r><w:t>after</w:t></w:r>"#,
        ));
        let context = [("w", crate::namespace::W_NS)];
        let total = paragraph
            .collapsed_hyperlink_source_total(&[0], Some(&context))
            .unwrap();
        let allowance = paragraph
            .collapsed_hyperlink_source_allowance(Some(&context))
            .unwrap();
        assert!(
            allowance >= total,
            "collapsed reservation {total} exceeds allowance {allowance}"
        );
        let mut removed = vec![false; paragraph.runs.len()];
        removed[0] = true;
        paragraph
            .remove_runs_core(&removed, Some(&context))
            .unwrap();
        let placeholder = paragraph
            .extra_xml
            .iter()
            .map(|(_, raw)| raw)
            .find(|raw| !raw.is_empty())
            .expect("collapsed hyperlink placeholder");
        assert!(
            total >= placeholder.len(),
            "aggregate estimate {total} under-counts replacement {}: {}",
            placeholder.len(),
            String::from_utf8_lossy(placeholder)
        );
        let mut output = Vec::new();
        paragraph
            .write_xml_core(
                &mut Writer::new(&mut output),
                None,
                XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        let output = String::from_utf8(output).unwrap();
        assert!(output.contains("target"), "{output}");
        assert!(output.contains("<x:raw/>"), "{output}");
        assert_eq!(output.matches("xmlns:x=").count(), 1, "{output}");
        // The mutation result reopens under the same source frame, keeps its
        // remaining text and repeats its Source bytes exactly.
        assert_eq!(paragraph.text(), "after");
        let inner = output
            .strip_prefix("<w:p>")
            .and_then(|rest| rest.strip_suffix("</w:p>"))
            .expect("bare source paragraph root");
        let reopened = CT_P::from_xml_fragment_checked(
            format!(
                r#"<w:p xmlns:w="{w}">{inner}</w:p>"#,
                w = crate::namespace::W_NS
            )
            .as_bytes(),
        )
        .unwrap();
        assert_eq!(reopened.text(), "after");
        let mut second = Vec::new();
        reopened
            .write_xml_core(
                &mut Writer::new(&mut second),
                None,
                XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        assert_eq!(second, output.as_bytes());
    }

