    #[test]
    fn public_comment_anchor_removal_keeps_prior_paragraph_on_collapsed_refusal() {
        let mut paragraph = parse_paragraph(
            r#"<w:commentRangeStart w:id="7"/><w:hyperlink xmlns:x="urn:producer" w:anchor="target"><w:r><w:commentReference w:id="7"/></w:r><x:raw/></w:hyperlink><w:r><w:t>after</w:t></w:r><w:commentRangeEnd w:id="7"/>"#,
        );
        // Fault injection, not an old-source RED: the collapsed-root fill is
        // refused after run removal, so the public remover must retain the
        // prior paragraph instead of publishing the half-removed candidate.
        let before = paragraph.clone();
        FORCE_COLLAPSED_REMOVAL_REFUSAL.with(|flag| flag.set(true));
        paragraph.remove_comment_anchors(&[7]);
        FORCE_COLLAPSED_REMOVAL_REFUSAL.with(|flag| flag.set(false));
        assert_eq!(
            paragraph, before,
            "a refused collapsed removal must leave the prior paragraph installed"
        );
        // Positive control: the same removal completes once the injected
        // refusal is withdrawn.
        paragraph.remove_comment_anchors(&[7]);
        assert!(paragraph.comment_ranges.is_empty());
        assert_eq!(paragraph.runs.len(), 1);
        assert_eq!(paragraph.text(), "after");
    }

